Repo: node-express-api
File: src/controllers/pagination.js
Context: Helper that adds pagination metadata to response objects.
Current implementation:
```js
function paginate(results, page, limit) {
  const total = results.length;
  const start = (page - 1) * limit;
  const end = page * limit;
  const data = results.slice(start, end);
  return {
    page,
    limit,
    total,
    data,
  };
}
module.exports = { paginate };
```
